void InitializePositionCapture(const std::filesystem::path& directory)noexcept{try{auto& s=S();if(s.enabled)return;std::string station;if(!Sealed(station))return;auto path=directory/"position-capture.request";std::error_code error;auto size=std::filesystem::file_size(path,error);if(error||size>512)return;std::ifstream f(path);std::string text{std::istreambuf_iterator<char>(f),{}};position_capture::Request request;if(!position_capture::Parse(text,station,request))return;std::lock_guard<std::mutex> lock(s.mutex);s.directory=directory;s.request=request;s.stopping=false;s.enabled=true;s.worker=std::thread(Worker);Event("explicit-sealed-MMGP1-enabled");}catch(...){}}
